CREATE TABLE customers(id varchar(100) PRIMARY KEY,display_name varchar(255) NOT NULL,status varchar(20) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(100) PRIMARY KEY,customer_id varchar(100) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(20) NOT NULL CHECK(status IN('ACTIVE','FROZEN','CLOSED')),max_transfer numeric(19,3) NOT NULL DEFAULT 10000 CHECK(max_transfer>0),receive_enabled boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(account_id varchar(100) REFERENCES accounts(id) ON DELETE RESTRICT,principal varchar(100) NOT NULL,can_debit boolean NOT NULL DEFAULT false,can_receive boolean NOT NULL DEFAULT true,PRIMARY KEY(account_id,principal));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(100) NOT NULL,to_account_id varchar(100) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(20) NOT NULL CHECK(status IN('COMPLETED','REJECTED')),rejection_code varchar(64),created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz NOT NULL,requested_by varchar(100) NOT NULL,correlation_id uuid NOT NULL);
CREATE INDEX payments_from ON payments(from_account_id,created_at);CREATE INDEX payments_to ON payments(to_account_id,created_at);CREATE INDEX payments_created ON payments(created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(6) NOT NULL CHECK(entry_type IN('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR(entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE TABLE rate_buckets(principal varchar(100) PRIMARY KEY,window_start timestamptz NOT NULL,hits integer NOT NULL);
CREATE FUNCTION immutable_financial_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial record is immutable';END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE FUNCTION immutable_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.rejection_code IS DISTINCT FROM 'PROCESSING' THEN RAISE EXCEPTION 'Payment is immutable'; END IF; RETURN NEW;END $$;
CREATE TRIGGER immutable_payment BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_payment();
